    questions: [
      { lv: 1, q: "Mô hình 3Cs được giới thiệu bởi ai, trong cuốn sách nào?", a: "Kenichi Ohmae, The Mind of the Strategist (1982)", w: ["Philip Kotler, Marketing Management (1967)","Michael Porter, Competitive Strategy (1980)","Igor Ansoff, Corporate Strategy (1965)"], e: "Ohmae, khi đó là partner của McKinsey tại Tokyo, gọi đây là \"tam giác chiến lược\" (strategic triangle). Bản tiếng Anh của sách ra năm 1982." },
      { lv: 1, q: "Ba chữ C trong mô hình gốc của Ohmae là gì?", a: "Customer, Corporation (Company), Competitors", w: ["Customer, Cost, Convenience","Company, Channel, Communication","Customer, Content, Context"], e: "Ohmae dùng chữ Corporation; phần lớn tài liệu sau này viết là Company. Customer, Cost, Convenience là một phần của 4Cs (Lauterborn)." },
      { lv: 1, q: "Theo Ohmae, một chiến lược thành công cần đạt được điều gì trong tam giác chiến lược?", a: "Đáp ứng nhu cầu khách hàng tốt hơn đối thủ, dựa trên thế mạnh của chính công ty", w: ["Đạt chi phí thấp nhất ngành bất kể khách hàng cần gì","Sao chép nhanh các sản phẩm thành công của đối thủ","Giành thị phần lớn nhất ở mọi phân khúc cùng lúc"], e: "Trọng tâm là lợi thế tương đối: khớp thế mạnh công ty với nhu cầu khách hàng theo cách khác biệt so với đối thủ." },
      { lv: 2, q: "Nếu công ty và đối thủ đáp ứng cùng một nhu cầu theo cùng một cách, theo logic 3Cs điều gì dễ xảy ra?", a: "Khách hàng không thấy khác biệt, cạnh tranh trượt dần thành cuộc chiến giá", w: ["Cả hai cùng tăng được biên lợi nhuận","Quy mô thị trường tự động mở rộng","Doanh nghiệp lớn hơn luôn thắng nhờ thương hiệu"], e: "Không có khác biệt trong cách đáp ứng nhu cầu, khách chỉ còn so sánh giá. Đó là lý do 3Cs buộc người làm chiến lược nhìn đồng thời cả đối thủ." },
      { lv: 2, q: "Một chuỗi bánh mì phát hiện 60% khách văn phòng muốn nhận hàng trong dưới 3 phút vào giờ cao điểm. Thông tin này thuộc C nào?", a: "Customer", w: ["Company","Competitors","Không thuộc 3Cs mà thuộc PESTEL"], e: "Đây là nhu cầu và tiêu chí mua của khách hàng. Nó sẽ trở thành lợi thế nếu Company có năng lực phục vụ nhanh hơn Competitors." },
      { lv: 2, q: "Thông tin nào thuộc phần phân tích Company trong 3Cs?", a: "Năng lực sản xuất, công nghệ, tài chính và văn hoá nội bộ", w: ["Thị phần và chiến lược giá của đối thủ dẫn đầu","Hành vi mua và tiêu chí lựa chọn của khách","Tỷ lệ lạm phát và chính sách thuế"], e: "Company là các nguồn lực và năng lực bên trong. Lạm phát và thuế là yếu tố vĩ mô, thường đưa vào Context ở mô hình 5Cs hoặc PESTEL." },
      { lv: 1, q: "Ohmae gợi ý chiến lược dựa trên khách hàng có thể phân khúc theo hai cách nào?", a: "Theo mục đích sử dụng của khách và theo độ phủ khách hàng tối ưu chi phí", w: ["Theo độ tuổi và theo giới tính","Theo vùng địa lý và theo nền tảng mạng xã hội","Theo mức giá và theo kiểu bao bì"], e: "Ohmae nói về segmenting by objectives (khách dùng sản phẩm để làm gì) và segmenting by customer coverage (phục vụ bao nhiêu khách thì chi phí marketing còn hiệu quả)." },
      { lv: 1, q: "Mô hình 5Cs mở rộng từ 3Cs bổ sung thêm hai yếu tố nào?", a: "Collaborators và Context (hay Climate)", w: ["Cost và Convenience","Channel và Communication","Culture và Creativity"], e: "Collaborators là đối tác, nhà cung cấp, nhà phân phối. Context là môi trường vĩ mô, có thể phân tích sâu bằng PESTEL." },
      { lv: 1, q: "Mô hình nào hay bị nhầm với 3Cs, do Robert Lauterborn đề xuất năm 1990 để nhìn 4P từ phía khách hàng?", a: "4Cs: Consumer, Cost, Convenience, Communication", w: ["5Cs: Company, Customers, Competitors, Collaborators, Context","7Cs của trải nghiệm khách hàng số","3Vs: Valued customer, Value proposition, Value network"], e: "4Cs của Lauterborn là phiên bản lấy khách hàng làm trung tâm của marketing mix, khác hoàn toàn mục đích phân tích chiến lược của 3Cs." },
      { lv: 1, q: "Ohmae gọi những yếu tố quyết định thành bại trong một ngành mà chiến lược phải tập trung nguồn lực vào là gì?", a: "Key Factors for Success (KFS)", w: ["Key Performance Indicators (KPI)", "Unique Selling Proposition (USP)", "Critical Path Method (CPM)"], e: "Ohmae khuyên dồn nguồn lực vào một vài KFS của ngành thay vì dàn trải. KPI là chỉ số đo lường; USP là khái niệm quảng cáo của Rosser Reeves." },
      { lv: 2, q: "Hãng mỹ phẩm nội địa thấy hàng ngoại chiếm phân khúc cao cấp, khách trẻ cần sản phẩm hợp khí hậu nóng ẩm, còn công ty mạnh về R&D thảo mộc bản địa. Hướng đi nào khớp logic 3Cs nhất?", a: "Dòng sản phẩm thiết kế riêng cho da châu Á khí hậu nóng ẩm, dựa trên nguyên liệu bản địa", w: ["Giảm giá thấp hơn hàng ngoại 30% cho mọi dòng", "Sao chép dòng cao cấp bán chạy của hãng ngoại", "Tập trung xuất khẩu sang châu Âu"], e: "Phương án này nối cả ba đỉnh: nhu cầu thật của khách (Customer), thế mạnh riêng (Company) và khoảng trống hàng ngoại chưa phục vụ tốt (Competitors)." },
      { t: "multi", lv: 2, q: "Những thông tin nào thuộc phần phân tích Competitors?", a: ["Cấu trúc chi phí ước tính của đối thủ chính", "Cách đối thủ định vị và truyền thông", "Phản ứng của đối thủ khi ta giảm giá lần trước"], w: ["Tỷ lệ khách quay lại của chính công ty", "Ngân sách R&D của công ty"], e: "Hai lựa chọn còn lại là dữ liệu nội bộ, thuộc Company." },
      { lv: 2, q: "So với SWOT, điểm khác biệt chính của 3Cs là gì?", a: "Đặt đối thủ thành một trục riêng và buộc so sánh trực tiếp cách mình và đối thủ phục vụ khách", w: ["3Cs chỉ dùng được cho doanh nghiệp B2B", "3Cs bỏ qua hoàn toàn năng lực nội bộ", "3Cs chỉ phân tích môi trường vĩ mô"], e: "Trong SWOT, đối thủ thường bị gộp vào ô Threats. 3Cs giữ đối thủ như một góc nhìn ngang hàng với khách hàng và công ty." },
      { lv: 3, q: "Trong bài \"Getting Back to Strategy\" (HBR, 1988), Ohmae cảnh báo điều gì?", a: "Chiến lược bắt đầu bằng việc đánh bại đối thủ dễ quên mất khách hàng; nên bắt đầu từ việc phục vụ nhu cầu khách tốt hơn", w: ["Doanh nghiệp nên bỏ qua khách hàng và tập trung chi phí", "Mọi ngành rồi sẽ chỉ còn một doanh nghiệp", "Phân tích đối thủ là việc không cần thiết"], e: "Ohmae cho rằng quá ám ảnh đối thủ khiến doanh nghiệp chạy theo nhau, trong khi giá trị thật đến từ câu hỏi khách cần gì." },
      { lv: 3, q: "Áp 3Cs cho nền tảng gọi xe, nơi tài xế vừa là đối tác vừa quyết định chất lượng dịch vụ, sẽ gặp hạn chế gì?", a: "Mô hình không có chỗ cho bên thứ tư như đối tác; nên mở rộng sang 5Cs với Collaborators", w: ["Không xác định được ai là khách hàng", "Nền tảng gọi xe không có đối thủ", "3Cs không áp dụng được cho dịch vụ"], e: "Với mô hình nền tảng nhiều bên, chất lượng phụ thuộc lớn vào đối tác, nên Collaborators cần được phân tích riêng." }
    ]
