    dia: { type: "matrix", title: "Bốn hướng tăng trưởng", x: "Sản phẩm: Hiện có → Mới", y: "Thị trường: Mới ↑ · Hiện có ↓", cells: [["Phát triển thị trường", "Sản phẩm cũ, thị trường mới"], ["Đa dạng hoá", "Rủi ro cao nhất"], ["Thâm nhập thị trường", "Rủi ro thấp nhất"], ["Phát triển sản phẩm", "Sản phẩm mới, khách hiện có"]], tone: ["m", "s", "l", "m"] },
