      { lv: 2, q: "Vì sao thâm nhập thị trường thường được xem là rủi ro thấp nhất?", a: "Doanh nghiệp đã hiểu cả sản phẩm lẫn khách hàng", w: ["Vì luật pháp bảo hộ thị trường hiện có","Vì không có đối thủ trong thị trường hiện tại","Vì không cần ngân sách marketing"], e: "Rủi ro thấp nhưng tăng trưởng có giới hạn, nhất là khi thị trường đã bão hoà." },
      { lv: 2, q: "Hãng xe máy điện vốn bán cho người đi làm ở đô thị, nay bán cùng mẫu xe cho các công ty giao hàng. Đây là chiến lược nào?", a: "Phát triển thị trường", w: ["Thâm nhập thị trường", "Phát triển sản phẩm", "Đa dạng hoá"], e: "Thị trường mới không nhất thiết là quốc gia mới; phân khúc khách mới (B2B thay vì B2C) cũng là phát triển thị trường." },
      { lv: 2, q: "Một hãng sữa mở chuỗi khách sạn nghỉ dưỡng. Đây là dạng tăng trưởng nào?", a: "Đa dạng hoá không liên quan", w: ["Đa dạng hoá liên quan", "Phát triển sản phẩm", "Phát triển thị trường"], e: "Không có điểm chung về công nghệ, khách hàng hay kênh giữa sữa và khách sạn." },
      { t: "multi", lv: 2, q: "Những hoạt động nào thuộc thâm nhập thị trường?", a: ["Giảm giá để giành khách của đối thủ", "Tăng tần suất mua qua chương trình thành viên", "Tăng độ phủ điểm bán trong khu vực hiện tại"], w: ["Ra mắt dòng sản phẩm mới", "Xuất khẩu sang nước khác"], e: "Thâm nhập là bán nhiều hơn sản phẩm hiện có cho thị trường hiện có." },
      { lv: 3, q: "Vì sao mở sang nước khác với sản phẩm cũ thường rủi ro hơn vẻ ngoài?", a: "Khách hàng, kênh, quy định và đối thủ đều mới; thực tế sản phẩm cũng thường phải điều chỉnh", w: ["Vì sản phẩm cũ không được phép xuất khẩu", "Vì ma trận Ansoff cấm phát triển thị trường", "Vì chi phí sản xuất luôn tăng gấp đôi"], e: "Ranh giới giữa các ô trong thực tế không rõ ràng; một bước \"phát triển thị trường\" có thể gần với đa dạng hoá." },
      { lv: 3, q: "Hạn chế chính của ma trận Ansoff là gì?", a: "Chỉ chỉ ra hướng tăng trưởng, không cho biết hướng nào khả thi hay sinh lời", w: ["Có quá nhiều ô để lựa chọn", "Không phân biệt sản phẩm và thị trường", "Chỉ áp dụng cho doanh nghiệp bán lẻ"], e: "Cần kết hợp với phân tích thị trường, năng lực (VRIO) và tài chính để chọn hướng." }
